<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {useSessionStore} from '@/stores/session'
import {useBusiness} from '@/composables/useBusiness'
import {recordId,rowData,rowsOf,versionOf,type BusinessData} from '@/api/modules/business'
import {isQuoteData,money,type QuoteData,type TradeRecord} from '@/api/modules/trade'
import {uuid} from '@/business/model'
import ApiErrorAlert from '@/components/ApiErrorAlert.vue'
const props=defineProps<{quote:TradeRecord;disabled:boolean}>(),emit=defineEmits<{selection:[{hold_id:string;adjusted_quote_sha256:string;quote:QuoteData}|null];busy:[boolean]}>()
const session=useSessionStore(),ui=useBusiness(()=>({token:session.token,accountId:session.account?.id||'',partyId:session.selectedId,sessionTag:session.expiresAt||'',domain:'trade-coupon'})),grants=ref<BusinessData[]>([]),hold=ref<BusinessData|null>(null),chosen=ref('')
const key=()=>`ops.coupon.${session.account?.id}.${session.selectedId}.${props.quote.id}`
const adjusted=computed(()=>{const d=hold.value&&rowData(hold.value);return d&&isQuoteData(d.adjusted_quote)?d.adjusted_quote:null})
const available=computed(()=>grants.value.filter(g=>g.current_status==='AVAILABLE'&&['PRODUCTION_CREDIT','PRODUCTION_FREE','SERVICE_CREDIT'].includes(String((rowData(g).template as BusinessData|undefined)?.kind))))
function publish(){const d=hold.value&&rowData(hold.value);emit('selection',hold.value&&adjusted.value&&typeof d?.adjusted_quote_sha256==='string'?{hold_id:recordId(hold.value),adjusted_quote_sha256:d.adjusted_quote_sha256,quote:adjusted.value}:null)}
watch(hold,()=>{publish();try{if(hold.value)sessionStorage.setItem(key(),JSON.stringify({session:session.expiresAt,hold:hold.value}));else sessionStorage.removeItem(key())}catch{/* current request remains in memory */}})
watch(()=>ui.busy.value||!!ui.pending.value,v=>emit('busy',v),{immediate:true})
watch(()=>[session.selectedId,session.revision,session.token,props.quote.id],()=>{grants.value=[];hold.value=null;chosen.value='';emit('selection',null)})
watch(ui.securityRevision,()=>{grants.value=[];hold.value=null;chosen.value='';emit('selection',null)})
async function load(){const r=await ui.load('/redemption/grants','required');if(r)grants.value=rowsOf(r)}
async function select(){const g=available.value.find(g=>recordId(g)===chosen.value);if(!g||versionOf(g)===null||props.quote.kind!=='QUOTE')return;const r=await ui.execute({path:`/redemption/grants/${recordId(g)}/checkout`,body:{quote_id:props.quote.id},method:'POST',party:'required',version:versionOf(g)!,label:'选择原报价的制作权益',readPath:`/redemption/grants/${recordId(g)}`,readParty:'required'});if(r)hold.value=r}
async function release(){if(!hold.value||versionOf(hold.value)===null)return;const r=await ui.execute({path:`/redemption/holds/${recordId(hold.value)}/release`,body:{},method:'POST',party:'required',version:versionOf(hold.value)!,label:'释放本次未下单的券',readPath:`/redemption/grants/${rowData(hold.value).grant_id}`,readParty:'required'});if(r){hold.value=null;await load()}}
async function retry(){const r=await ui.execute();if(r&&r.kind==='COUPON_HOLD'){if(r.current_status==='HELD')hold.value=r;else hold.value=null}}
onMounted(async()=>{try{const saved=JSON.parse(sessionStorage.getItem(key())||'null'),h=saved?.hold,d=h&&rowData(h);if(saved?.session===session.expiresAt&&uuid(h?.id)&&isQuoteData(d?.adjusted_quote)&&d.quote_id===props.quote.id&&d.quote_sha256===props.quote.content_sha256&&Date.parse(String(d.expires_at))>Date.now()){const g=await ui.load(`/redemption/grants/${d.grant_id}`,'required');if(g?.current_status==='HELD'&&rowData(g).checkout_hold_id===h.id)hold.value=h}}catch{/* An unverified saved selection is never applied. */}})
onBeforeRouteLeave(()=>!ui.pending.value);onBeforeRouteUpdate(()=>!ui.pending.value)
</script>
<template><section class="supply-card" data-testid="trade-coupon-selector"><h2>本次选用制作权益</h2><p>先锁定原报价适用的本券，再核对抵扣金额与付款节点。已实际核销的券不随现金退款退回。</p><ApiErrorAlert :error="ui.error.value"/><p v-if="ui.notice.value" role="status">{{ui.notice.value}}</p><section v-if="ui.pending.value" class="supply-warning"><p>选券或释放结果待核对，请恢复同一次请求。</p><button class="outline" :disabled="ui.busy.value" @click="ui.check(ui.pending.value.readPath||'/redemption/grants','required')">核对原券</button><button class="outline" :disabled="ui.busy.value||!ui.pending.value.checked" @click="retry">恢复原请求</button></section><template v-if="!hold"><button class="outline" :disabled="disabled||ui.busy.value||!!ui.pending.value" @click="load">读取本人可用制作权益</button><label v-if="available.length">选择已取得的实际权益<select v-model="chosen" :disabled="disabled||ui.busy.value||!!ui.pending.value"><option value="">请选择</option><option v-for="g in available" :key="recordId(g)" :value="recordId(g)">{{(rowData(g).template as BusinessData)?.title}} · 到期 {{new Date(String(rowData(g).expires_at)).toLocaleString('zh-CN',{hour12:false})}}</option></select></label><button v-if="available.length" class="outline" :disabled="disabled||ui.busy.value||!!ui.pending.value||!chosen" @click="select">按原报价试算并锁定本券</button></template><template v-else-if="adjusted"><dl class="supply-facts"><div><dt>原报价</dt><dd>{{props.quote.kind==='QUOTE'?money(props.quote.data.total_minor):''}}</dd></div><div><dt>本次权益抵扣</dt><dd>{{money(adjusted.discount!.discount_minor)}}</dd></div><div><dt>本次实际应付</dt><dd class="trade-amount">{{money(adjusted.total_minor)}}</dd></div><div><dt>锁定截止</dt><dd>{{new Date(String(rowData(hold).expires_at)).toLocaleString('zh-CN',{hour12:false})}}</dd></div></dl><p v-if="adjusted.total_minor===0" class="supply-warning">本单由已选权益承担费用，没有现金分期与付款凭据；确认订单后仍须实际审核和开工，开工才核销本权益。</p><p v-for="i in adjusted.installments" :key="i.key">{{i.key}} · {{money(i.allocations.reduce((n,a)=>n+a.amount_minor,0))}}</p><button class="outline" :disabled="disabled||ui.busy.value||!!ui.pending.value" @click="release">明确释放本次锁定</button></template></section></template>
